-- ----------------------------
-- Table structure for sys_approval_chain_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_approval_chain_config`;
CREATE TABLE `sys_approval_chain_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `module_id` bigint NULL DEFAULT 0 COMMENT '所属模块ID 0表示不属于模块',
  `up_step` int NULL DEFAULT 0 COMMENT '上一步步骤',
  `current_step` int NULL DEFAULT 1 COMMENT '当前步骤',
  `next_step` int NULL DEFAULT 2 COMMENT '下一步步骤',
  `approval_chain_type_id` bigint NULL DEFAULT NULL COMMENT '审批链分类id',
  `approval_rule` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批规则',
  `reject_rule` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '驳回规则',
  `role_approval_percent` int NULL DEFAULT NULL COMMENT '0~100 approval_rule为3时设置需要审批人数的百分比',
  `approve_role_id` bigint NULL DEFAULT NULL COMMENT '审批角色组  sys_role表的id 审批角色组  approvale_rule 为1  2  3时',
  `approver_id` bigint NULL DEFAULT NULL COMMENT '审批人  sys_user表的id  approval_rule为0时',
  `delegate_approver_id` bigint NULL DEFAULT NULL COMMENT '移交人id  approval_rule 为0时使用',
  `skipped` tinyint NOT NULL DEFAULT 0 COMMENT '是否跳过步骤  1:跳过  0:不跳过',
  `showed` tinyint NOT NULL DEFAULT 1 COMMENT '1:显示，0:隐藏',
  `child_module_ids` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '子模块集合Id, 英文逗号分隔',
  `current_status_id` bigint NOT NULL DEFAULT 0 COMMENT '当前状态ID',
  `next_status_id` bigint NOT NULL DEFAULT 0 COMMENT '下一状态ID',
  `auto_approved` int NULL DEFAULT 0 COMMENT '1:自动审批，0:不能自动审批，默认为0',
  `auto_approved_time` int NULL DEFAULT NULL COMMENT '系统自动办理时间  auto_approved为1时必填',
  `deadline_time` int NULL DEFAULT NULL COMMENT '办理人未办理的最迟时间  auto_approved_time为0时可填',
  `button_list` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '按钮Id列表',
  `collaborated` tinyint NULL DEFAULT 0 COMMENT '是否协同办理 0:否  1:是',
  `repeated` tinyint NULL DEFAULT 0 COMMENT '是否可以重复提交 0:否  1:是',
  `msg_template_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '消息模板Id集合, 英文逗号分隔',
  `default_flag` tinyint NULL DEFAULT 0 COMMENT '是否默认，1：是，0：否',
  `subject_id` bigint NOT NULL DEFAULT 0 COMMENT '所属主体',
  `project_no` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '应用编码',
  `created_by` bigint NULL DEFAULT NULL COMMENT '模拟操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE,
  CONSTRAINT `sys_approval_chain_config_chk_1` CHECK (`skipped` in (0,1)),
  CONSTRAINT `sys_approval_chain_config_chk_2` CHECK (`showed` in (0,1)),
  CONSTRAINT `sys_approval_chain_config_chk_3` CHECK (`collaborated` in (0,1)),
  CONSTRAINT `sys_approval_chain_config_chk_4` CHECK (`repeated` in (0,1)),
  CONSTRAINT `sys_approval_chain_config_chk_5` CHECK (`default_flag` in (0,1))
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统表-审批链配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_approval_chain_config
-- ----------------------------

