  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '1删除0正常',
  PRIMARY KEY (`id`) USING BTREE,
  CONSTRAINT `sys_button_chk_1` CHECK (`showed` in (0,1)),
  CONSTRAINT `sys_button_chk_2` CHECK (`deleted` in (0,1))
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '按钮信息配置表' ROW_FORMAT = DYNAMIC;

