  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_module`(`module_id` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 59 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统表-字段值业务配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_field_value
-- ----------------------------

-- ----------------------------
-- Table structure for sys_interaction_permission
-- ----------------------------
DROP TABLE IF EXISTS `sys_interaction_permission`;
CREATE TABLE `sys_interaction_permission`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `module_id` bigint NULL DEFAULT NULL COMMENT '模块id',
  `module_code` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模块标识',
  `type` tinyint NULL DEFAULT NULL COMMENT '交互权限类型.1:申请 2:编辑 3:查看',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '权限名称',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '权限编码',
  `sort` int NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态',
  `subject_id` bigint NOT NULL DEFAULT 0 COMMENT '所属主体',
  `project_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '应用编码',
  `created_by` bigint NULL DEFAULT NULL COMMENT '模拟操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `code`(`code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '交互权限表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_interaction_permission
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pid` bigint NOT NULL DEFAULT 0 COMMENT '父级id',
  `subject_id` bigint NULL DEFAULT 0 COMMENT '所属主体',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '菜单名称',
  `param` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '参数',
  `menu_type` tinyint NOT NULL DEFAULT 1 COMMENT '菜单类型.1:导航 2:页面 3:标签 4:表',
  `category` tinyint NOT NULL DEFAULT 1 COMMENT '菜单分类.1:业务菜单 2:系统菜单',
  `img_default` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '默认图标',
  `img_active` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '选中后图标',
  `module_id` bigint NULL DEFAULT 0 COMMENT '关联模块id',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序',
  `showed` tinyint NULL DEFAULT 1 COMMENT '0隐藏，1显示',
  `enabled` tinyint NULL DEFAULT 1 COMMENT '1启用，0停用',
  `doc_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '帮助文档地址',
  `doc_name` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '帮助文档名称',
  `video_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '演示视频地址',
  `video_name` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '帮助视频名',
  `project_no` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '应用编码',
  `created_by` bigint NULL DEFAULT NULL COMMENT '模拟操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE,
  CONSTRAINT `sys_menu_chk_1` CHECK (`showed` in (0,1)),
  CONSTRAINT `sys_menu_chk_2` CHECK (`enabled` in (0,1))
) ENGINE = InnoDB AUTO_INCREMENT = 160 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统菜单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_menu
-- ----------------------------

-- ----------------------------
-- Table structure for sys_message_record
-- ----------------------------
DROP TABLE IF EXISTS `sys_message_record`;
CREATE TABLE `sys_message_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '项目编号',
  `subject_id` bigint NOT NULL DEFAULT 0 COMMENT '主体ID',
  `receiver` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '接收人(企业微信账号/手机号)',
  `message_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '消息类型: text, markdown, sms',
  `message_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '消息标题',
  `message_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '消息内容',
  `send_status` int NOT NULL DEFAULT 0 COMMENT '发送状态: 0-成功, 其他为微信返回的错误码',
  `response_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '底层发送接口响应结果',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 342 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '消息发送记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_message_record
-- ----------------------------

-- ----------------------------
-- Table structure for sys_module
-- ----------------------------
DROP TABLE IF EXISTS `sys_module`;
CREATE TABLE `sys_module`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '项目编号',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '公司主体ID',
  `source_subjects` json NULL COMMENT '数据来源主体ID集合',
  `biz_def_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否模块业务定义: 0-否, 1-是',
  `module_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块唯一编码，如 MOD-STUDENT-FULL',
  `module_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块名称',
  `module_desc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模块描述',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '父模块ID，0表示根模块',
  `detail_module_id` bigint NULL DEFAULT NULL COMMENT '详情模块ID(用于申请、编辑和查看按钮的显示逻辑)',
  `primary_table` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主实体（主表）名称，folder类型可为空',
  `module_type` enum('LIST','DETAIL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块类型: 列表、详情',
  `category` tinyint NOT NULL DEFAULT 1 COMMENT '模块类别: 1-业务模块, 2-系统模块',
  `approval_required` tinyint NULL DEFAULT NULL COMMENT '是否启用审批',
  `relate_search_field` varchar(75) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联查询字段',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '同级排序顺序，数字越小越靠前',
  `table_header` json NULL COMMENT '列表表头配置',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `created_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_module_code`(`project_no` ASC, `subject_id` ASC, `module_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 216 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '模块基本信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_module
-- ----------------------------

-- ----------------------------
-- Table structure for sys_module_field
-- ----------------------------
DROP TABLE IF EXISTS `sys_module_field`;
CREATE TABLE `sys_module_field`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `module_id` bigint NOT NULL COMMENT '所属模块ID',
  `field_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '字段类型: SIMPLE-简单字段, COMBINE-组合字段',
  `field_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '字段编码',
  `table_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物理表名（SIMPLE专属，COMBINE时为*）',
  `display_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '显示名称（COMBINE专属，SIMPLE可由物理字典或注释翻译）',
  `biz_key_order` int NULL DEFAULT NULL COMMENT '业务唯一标识顺序',
  `source_mapping` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物理字段映射JSON（COMBINE专属）',
  `transformer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '转换表达式',
  `transformer_env` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'none' COMMENT '转换环境: database, frontend, none',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1341 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '模块字段配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_module_field
-- ----------------------------

-- ----------------------------
-- Table structure for sys_module_status
-- ----------------------------
DROP TABLE IF EXISTS `sys_module_status`;
CREATE TABLE `sys_module_status`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模块状态ID',
  `module_id` bigint NOT NULL DEFAULT 0 COMMENT '模块ID',
  `status_pid` bigint NOT NULL COMMENT '状态父ID',
  `status_id` bigint NOT NULL DEFAULT 0 COMMENT '状态ID',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `created_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 244 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '模块状态表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_module_status
-- ----------------------------

-- ----------------------------
-- Table structure for sys_module_table
-- ----------------------------
DROP TABLE IF EXISTS `sys_module_table`;
CREATE TABLE `sys_module_table`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `module_id` bigint NOT NULL COMMENT '所属模块ID',
  `table_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表名',
  `table_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '表描述',
  `join_left_field` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联左字段（关联表中的字段）',
  `join_right_field` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联右字段（主表中的字段）',
  `relation_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关系类型: 1:1-一对一, N:1-多对一, 1:N-一对多',
  `read_only` tinyint NOT NULL DEFAULT 0 COMMENT '关联表是否只读',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序顺序',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_module_table`(`module_id` ASC, `table_name` ASC) USING BTREE,
  INDEX `idx_module_id`(`module_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 371 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '模块关联物理表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_module_table
-- ----------------------------

-- ----------------------------
-- Table structure for sys_monitor_controllog
-- ----------------------------
DROP TABLE IF EXISTS `sys_monitor_controllog`;
CREATE TABLE `sys_monitor_controllog`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID;自增主键',
  `subject_id` bigint NOT NULL COMMENT '主体ID;（多主体、多租户）',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主体名称',
  `actionName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '动作名称',
  `actionPath` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批动作图标',
  `actionTypeTitle` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批结果',
  `login_user_id` bigint NOT NULL COMMENT '登录用户ID',
  `login_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录用户名',
  `login_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人头像',
  `login_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人工号',
  `login_role_id` bigint NOT NULL COMMENT '登录用户的角色ID',
  `login_role_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人角色名称',
  `login_user_dept_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门ID;多个ID，用逗号分割',
  `login_user_dept_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门名称;多个名称，用逗号分割',
  `login_user_job_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '登录人岗位ID;多个ID，用逗号分割',
  `login_user_job_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录人岗位名称;多个名称，用逗号分割',
  `mock_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否mock标记;：0，否；1 是',
  `mock_user_id` bigint NULL DEFAULT 0 COMMENT '模拟用户ID',
  `mock_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户名称',
  `mock_user_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户头像',
  `mock_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户工号',
  `ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '日志发生的IP地址',
  `module_id` bigint NULL DEFAULT NULL COMMENT '模块ID',
  `module_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模块名称;系统设置/元件管理/',
  `order_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单据编号;审批链配置/FHSQ2409230955401/权限配置',
  `menu_id` bigint NULL DEFAULT NULL COMMENT '菜单ID',
  `menu_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '菜单名称',
  `data_id` bigint NULL DEFAULT NULL COMMENT '单据ID',
  `orderVersion` int NULL DEFAULT NULL COMMENT '单据版本号',
  `control_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单据操作名称;元件审核/权限配置/审批链配置',
  `operator_result` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作结果/执行结果/处理结果;成功/失败',
  `font_color` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字体颜色;获取系统中配置的颜色，默认为黑色',
  `browser` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'chrome' COMMENT '浏览器信息',
  `plat_form` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'windows' COMMENT '平台信息',
  `system_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '系统名称',
  `log_content` json NULL COMMENT '日志内容',
  `log_remark` json NOT NULL COMMENT '日志备注',
  `log_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '日志时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统监控操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_monitor_controllog
-- ----------------------------

-- ----------------------------
-- Table structure for sys_monitor_messagelog
-- ----------------------------
DROP TABLE IF EXISTS `sys_monitor_messagelog`;
CREATE TABLE `sys_monitor_messagelog`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID;自增主键',
  `subject_id` bigint NOT NULL COMMENT '主体ID;（多主体、多租户）',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主体名称',
  `actionName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '动作名称',
  `actionPath` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批动作图标',
  `actionTypeTitle` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批结果',
  `login_user_id` bigint NOT NULL COMMENT '登录用户ID',
  `login_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录用户名',
  `login_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人头像',
  `login_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人工号',
  `login_role_id` bigint NOT NULL COMMENT '登录用户的角色ID',
  `login_role_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人角色名称',
  `login_user_dept_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门ID;多个ID，用逗号分割',
  `login_user_dept_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '登录人部门名称;多个名称，用逗号分割',
  `login_user_job_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '登录人岗位ID;多个ID，用逗号分割',
  `login_user_job_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录人岗位名称;多个名称，用逗号分割',
  `mock_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否mock标记;：0，否；1 是',
  `mock_user_id` bigint NULL DEFAULT 0 COMMENT '模拟用户ID',
  `mock_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户名称',
  `mock_user_avater` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户头像',
  `mock_user_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟用户工号',
  `ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '日志发生的IP地址',
  `plat_form` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'windows' COMMENT '平台信息',
  `system_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '系统名称',
  `log_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '日志内容',
  `log_remark` json NOT NULL COMMENT '日志备注',
  `log_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '日志时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `index_0`(`id` ASC, `log_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统监控消息日志表' ROW_FORMAT = Dynamic;

