  `login_user_job_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录人岗位名称;多个名称，用逗号分割',
  `mock_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否mock标记;：0，否；1 是',
