  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `role_id` bigint NOT NULL COMMENT '角色ID（关联 sys_role.id）',
  `module_id` bigint NOT NULL COMMENT '模块ID（关联 sys_module.id）',
  `field_id` bigint NOT NULL COMMENT '字段ID（关联 sys_module_simple_field.id 或 sys_module_combine_field.id）',
  `readable` tinyint NOT NULL DEFAULT 1 COMMENT '是否可读: 0-否, 1-是',
  `writable` tinyint NOT NULL DEFAULT 1 COMMENT '是否可写(新增): 0-否, 1-是',
  `updatable` tinyint NOT NULL DEFAULT 1 COMMENT '是否可更新: 0-否, 1-是',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `updated_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_role_module_field`(`role_id` ASC, `module_id` ASC, `field_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 72599 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色模块字段权限配置表' ROW_FORMAT = DYNAMIC;

