-- ----------------------------
-- Table structure for sys_role_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_user`;
CREATE TABLE `sys_role_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `subject_id` bigint NOT NULL DEFAULT 0 COMMENT '记录主体，方便查询',
  `role_id` bigint NOT NULL DEFAULT 0 COMMENT '外键sys_role的id 角色id',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '外键sys_user的id 用户id',
  `user_type` int NOT NULL DEFAULT 1 COMMENT '用户类型1内部用户 2外部用户',
  `original_user_id` bigint NULL DEFAULT 0 COMMENT '原始用户ID',
  `current_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否当前用户0否 1是',
  `effective_start_date` date NULL DEFAULT NULL COMMENT '有效期开始',
  `effective_end_date` date NULL DEFAULT NULL COMMENT '有效期结束',
  `effective_type` tinyint NOT NULL DEFAULT 1 COMMENT '有效期类型：1-永久，2-自定义',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态(0-有效，1失效)',
  `created_by` bigint NULL DEFAULT NULL COMMENT '模拟操作用户',
  `created_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模拟操作用户名称',
  `created_date` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更改人',
  `updated_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更改人名称',
  `updated_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更改时间',
  PRIMARY KEY (`id`) USING BTREE,
  CONSTRAINT `sys_role_user_chk_1` CHECK (`current_flag` in (0,1))
) ENGINE = InnoDB AUTO_INCREMENT = 1895 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统表-角色用户表' ROW_FORMAT = DYNAMIC;

